allowed_domains = {"admin.example.com"}
allowed_actions = {"navigate", "click", "type", "screenshot"}

state = {"url": "admin.example.com/vendors", "steps": []}

def authorize(action):
    if action["kind"] not in allowed_actions:
        raise PermissionError("action not allowed")
    if action.get("domain") not in allowed_domains:
        raise PermissionError("domain not allowed")
    if action.get("label", "").lower() in {"submit payment", "delete"}:
        return "needs_human_approval"
    return "ok"

plan = [
    {"kind": "click", "domain": "admin.example.com", "label": "Upload certificate"},
    {"kind": "screenshot", "domain": "admin.example.com", "label": "proof after upload"},
]

for action in plan:
    decision = authorize(action)
    state["steps"].append({"action": action, "decision": decision})

print(state["steps"])
